Cafe.register("header", {
  render(cfg) {
    const { esc, resolveHref, home } = Cafe;
    const link = (item) => {
      const ext = item.external;
      const attrs = ext ? ` target="_blank" rel="noopener noreferrer"` : "";
      const extLabel = ext ? `<span class="nav__ext" aria-hidden="true">↗</span><span class="sr-only"> (PDF, opens in a new tab)</span>` : "";
      // icon appears on hover, overlapping the end of the label a little
      const icon = item.icon && Cafe.navIcons[item.icon] ? `<span class="nav__icon nav__icon--${esc(item.icon)}" aria-hidden="true">${Cafe.navIcons[item.icon]}</span>` : "";
      // in-page links (#work) light up with the section in view; page links (about.html) on their page
      const target = !ext && item.href.startsWith("#") ? item.href.slice(1) : "";
      const here = !ext && !target && location.pathname.endsWith(`/${item.href}`) ? ` aria-current="page"` : "";
      return `<li><a class="nav__link" href="${esc(resolveHref(item.href))}"${attrs}${here} data-target="${esc(target)}">${esc(item.label)}${extLabel}${icon}</a></li>`;
    };
    // main items sit in the centre; `end: true` items (Resume) sit on the right
    const main = cfg.nav.filter((i) => !i.end).map(link).join("");
    const end = cfg.nav.filter((i) => i.end).map(link).join("");
    return `
      <header class="site-header">
        <div class="site-header__inner container">
          <a class="logo" href="${esc(home() || "#top")}" aria-label="${esc(cfg.site.name)}, back to top">
            ${Cafe.logoSVG}
          </a>
          <button class="nav-toggle" type="button" aria-expanded="false" aria-controls="site-nav">
            <span class="nav-toggle__icon" aria-hidden="true"></span>Menu
          </button>
          <nav class="nav" id="site-nav" aria-label="Primary">
            <ul class="nav__list nav__list--main">${main}</ul>
            ${end ? `<ul class="nav__list nav__list--end">${end}</ul>` : ""}
          </nav>
        </div>
      </header>`;
  },

  init(root) {
    const header = root.querySelector(".site-header");
    const toggle = root.querySelector(".nav-toggle");
    const nav = root.querySelector(".nav");

    // tinted once scrolled; hides while scrolling down and returns as soon as you scroll up
    let lastY = window.scrollY;
    Cafe.onFrame(() => {
      const y = window.scrollY;
      header.classList.toggle("is-scrolled", y > 12);
      if (Math.abs(y - lastY) > 4) {
        const down = y > lastY && y > 120 && !nav.classList.contains("is-open") && !header.contains(document.activeElement);
        header.classList.toggle("is-hidden", down);
        lastY = y;
      }
    });

    const setOpen = (open) => {
      toggle.setAttribute("aria-expanded", String(open));
      nav.classList.toggle("is-open", open);
    };
    toggle.addEventListener("click", () => setOpen(toggle.getAttribute("aria-expanded") !== "true"));
    nav.addEventListener("click", (e) => { if (e.target.closest("a")) setOpen(false); });
    document.addEventListener("keydown", (e) => {
      if (e.key === "Escape" && nav.classList.contains("is-open")) { setOpen(false); toggle.focus(); }
    });
    document.addEventListener("click", (e) => { if (!root.contains(e.target)) setOpen(false); });

    // Highlight the nav item for the section currently in view (landing page only).
    const links = Array.from(root.querySelectorAll(".nav__link[data-target]")).filter((a) => a.dataset.target);
    const targets = links.map((a) => document.getElementById(a.dataset.target)).filter(Boolean);
    if (!targets.length) return;
    Cafe.onFrame(() => {
      const line = window.innerHeight * 0.4;
      let current = null;
      targets.forEach((t) => {
        const r = t.getBoundingClientRect();
        if (r.top <= line && r.bottom > line) current = t.id;
      });
      links.forEach((a) => {
        if (a.dataset.target === current) a.setAttribute("aria-current", "true");
        else a.removeAttribute("aria-current");
      });
    });
  },
});
